import {player,createCoins,canWalk,render,resetPlayer,burst} from './world.js';
import {initKeepsakes,updateTrail,milestones,productSvg,openLoom,openStudio,appearance,rug} from './keepsakes.js';
let pausedFrom='playing';
const $=id=>document.getElementById(id);
const emblems={sun:{name:'Sun',symbol:'☀'},moon:{name:'Moon',symbol:'☾'},mountain:{name:'Mountain',symbol:'▲'}};
const modes={demo:{target:3,sequence:3},explorer:{target:12,sequence:4},adventurer:{target:20,sequence:5}};
let state={phase:'start',emblem:'sun',mode:'demo',coins:[],target:3,tier:0,collected:0,puzzleSolved:false,earned:false};
let keys=new Set(),stick={x:0,z:0},puzzle={sequence:[],input:[],watching:false,generation:0,coin:null},last=performance.now(),toastTimer,revealTimer,sound=false,audio;
const ready=()=>state.collected>=state.target&&state.puzzleSolved;
const nearShrine=()=>Math.hypot(player.position.x,player.position.z)<2.8;
function snapshot(){return{phase:state.phase,emblem:state.emblem,mode:state.mode,collected:state.collected,target:state.target,appearance:{...appearance},wovenRug:rug.solved,puzzleSolved:state.puzzleSolved,earned:state.earned,player:{x:+player.position.x.toFixed(2),z:+player.position.z.toFixed(2)}}}
function tone(freq=620){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.18)}catch{}}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2400)}
function clearMovement(){keys.clear();stick={x:0,z:0};$('stick').style.transform='translate(-50%,-50%)'}
function update(){const target=state.target;$('mode-label').textContent=state.mode.toUpperCase()+' ADVENTURE';$('count').textContent=state.collected+' / '+target;$('objective').textContent=ready()?'Awaken your relic':state.collected===0?'Follow the golden light':state.collected===target-1?(state.puzzleSolved?'One coin to go':'Find the ancient echo'):'Explore the island';$('progress').replaceChildren(...Array.from({length:target},(_,i)=>{const el=document.createElement('i');el.className=i<state.collected?'filled':'';return el}));updateTrail();}
function chooseEmblem(name){if(!emblems[name])throw Error('Unknown emblem');state.emblem=name;document.querySelectorAll('[data-emblem]').forEach(b=>{const selected=b.dataset.emblem===name;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
function begin(mode=$('difficulty').value){if(!modes[mode])throw Error('Unknown difficulty');clearTimeout(revealTimer);puzzle.generation++;clearMovement();for(const id of ['start-dialog','puzzle-dialog','reward-dialog','wardrobe-dialog','trail-dialog','studio-dialog','loom-dialog'])if($(id).open)$(id).close();state={...state,phase:'playing',mode,target:3,tier:0,collected:0,puzzleSolved:false,earned:false};resetPlayer();const coins=[{x:0,z:5},{x:-5,z:-3},{x:5,z:-8,puzzle:true}];const extra=[[-2,0],[-3,-2],[-7,-5],[-9,-7],[2,-3],[3.5,-5.5],[0,2],[0,7],[3,2],[6,4],[8,5],[-2,4],[-4,3],[-5,1],[0,-2],[1,-1],[4,3]];for(let i=3;i<Math.max(12,modes[mode].target);i++){const [x,z]=extra[i-3];coins.push({x,z})}state.coins=coins.map((c,id)=>({...c,id,taken:false,locked:id>=3}));createCoins(state.coins,state.emblem);update();$('game').focus();notify('Your first keepsake awaits at 3 coins. The loom is beside the shore.');return snapshot()}
function reset(){clearMovement();puzzle.generation++;clearTimeout(revealTimer);state.phase='start';for(const id of ['puzzle-dialog','reward-dialog'])if($(id).open)$(id).close();$('start-dialog').showModal();return snapshot()}
function collect(coin){if(coin.taken)return;coin.taken=true;state.collected++;burst(coin.x,coin.z);tone(520+state.collected*100);update();notify(ready()?'The shrine is calling. Bring your relic home.':'Coin found! '+state.collected+' of '+state.target)}
function showSequence(){const generation=++puzzle.generation;puzzle.input=[];puzzle.watching=true;$('puzzle-replay').disabled=true;$('puzzle-feedback').textContent='Watch the symbols from left to right.';$('sequence').replaceChildren(...puzzle.sequence.map(n=>{const e=document.createElement('span');e.textContent=['☀','☾','▲'][n];return e}));document.querySelectorAll('[data-symbol]').forEach(b=>b.disabled=true);puzzle.sequence.forEach((n,i)=>setTimeout(()=>{if(generation!==puzzle.generation)return;[...$('sequence').children].forEach((el,j)=>el.classList.toggle('active',j===i));tone([500,660,820][n])},i*650));setTimeout(()=>{if(generation!==puzzle.generation)return;puzzle.watching=false;$('sequence').replaceChildren(...puzzle.sequence.map(()=>{const e=document.createElement('span');e.textContent='·';return e}));$('puzzle-feedback').textContent='Your turn. Repeat the symbols.';$('puzzle-replay').disabled=false;document.querySelectorAll('[data-symbol]').forEach(b=>b.disabled=false)},puzzle.sequence.length*650+450)}
function encounter(coin){state.phase='puzzle';clearMovement();puzzle.coin=coin;puzzle.sequence=Array.from({length:modes[state.mode].sequence},()=>Math.floor(Math.random()*3));$('puzzle-dialog').showModal();showSequence()}
function answer(n){if(puzzle.watching||state.phase!=='puzzle')return;if(n!==puzzle.sequence[puzzle.input.length]){puzzle.watching=true;$('puzzle-feedback').textContent='Your coins are safe. Watch and try again.';$('puzzle-replay').disabled=false;document.querySelectorAll('[data-symbol]').forEach(b=>b.disabled=true);tone(220);return}puzzle.input.push(n);$('sequence').children[puzzle.input.length-1].textContent=['☀','☾','▲'][n];tone([500,660,820][n]);if(puzzle.input.length===puzzle.sequence.length){puzzle.generation++;state.puzzleSolved=true;state.phase='playing';$('puzzle-dialog').close();collect(puzzle.coin);$('game').focus()}}
function awaken(){if(state.phase!=='playing'||!ready()||!nearShrine())return;state.phase='revealing';clearMovement();burst(0,0,60);tone(880);notify('Your story becomes a relic.');revealTimer=setTimeout(()=>{state.phase='reward';state.earned=true;const emblem=emblems[state.emblem];$('reward-symbol').textContent=emblem.symbol;$('reward-title').textContent='Your '+emblem.name+' Relic';$('reward-origin').textContent=state.collected+' coins. One ancient echo. Your story.';const item=milestones[state.tier];document.querySelector('.reward-sheet>p').textContent=item.type==='rug'?'The island’s patterns, imagined as a rug for your everyday space.':item.type==='trophy'?'A small monument to the adventure you completed.':'Your island emblem, imagined as a pendant you can carry with you.';$('design-label').textContent=emblem.name+' '+item.title.toLowerCase();$('reward-title').textContent='Your '+emblem.name+' '+item.title;document.querySelector('.reward-art').innerHTML=productSvg(item.type,state.emblem,item.metal)+'<span>DESIGN CONCEPT</span>';$('continue').hidden=state.tier>=milestones.length-1;$('continue').textContent=state.tier<milestones.length-1?'Next: '+milestones[state.tier+1].title+' at '+milestones[state.tier+1].coins+' coins':'Trail complete';$('reward-dialog').showModal()},1700)}
function move(dt){let x=stick.x+(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),z=stick.z+(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);const length=Math.hypot(x,z);if(length<.1)return false;if(length>1){x/=length;z/=length}const step=dt*4.3,nx=player.position.x+x*step,nz=player.position.z+z*step;if(canWalk(nx,player.position.z))player.position.x=nx;if(canWalk(player.position.x,nz))player.position.z=nz;const angle=Math.atan2(x,z),difference=Math.atan2(Math.sin(angle-player.rotation.y),Math.cos(angle-player.rotation.y));player.rotation.y+=difference*Math.min(1,dt*15);return true}
function frame(now){const dt=Math.min(.04,(now-last)/1000);last=now;let moving=false;if(state.phase==='playing'){moving=move(dt);for(const c of state.coins){if(!c.taken&&!c.locked&&Math.hypot(player.position.x-c.x,player.position.z-c.z)<.7){if(c.puzzle&&!state.puzzleSolved){encounter(c);break}else collect(c)}}const goal=ready()?{x:0,z:0}:state.coins.filter(c=>!c.taken&&!c.locked).sort((a,b)=>Math.hypot(a.x-player.position.x,a.z-player.position.z)-Math.hypot(b.x-player.position.x,b.z-player.position.z))[0];if(goal){const x=goal.x-player.position.x,z=goal.z-player.position.z;$('direction-arrow').style.transform='rotate('+Math.atan2(x,-z)+'rad)';$('direction-text').textContent=(ready()?'Return to the shrine':goal.puzzle?'Ancient echo':'Next coin')+' · '+Math.ceil(Math.hypot(x,z))+'m'}const shrine=ready()&&nearShrine(),loom=Math.hypot(player.position.x-3,player.position.z-5)<2;$('interact').disabled=!shrine&&!loom;$('interact').innerHTML=shrine?'<span>✦</span><small>SHRINE</small>':loom?'<span>▧</span><small>WEAVE</small>':'<span>✦</span><small>SHRINE</small>';$('interact').classList.toggle('ready',shrine||loom)}render(dt,now/1000,moving,ready(),state.phase==='revealing');requestAnimationFrame(frame)}
window.addEventListener('keydown',e=>{if(state.phase!=='playing')return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','e'].includes(k)){e.preventDefault();keys.add(k);if(k==='e')interact();else if(!e.repeat)move(.045)}});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',clearMovement);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearMovement()});
let pointer=null;function steer(e){const r=$('joystick').getBoundingClientRect(),x=e.clientX-r.left-r.width/2,z=e.clientY-r.top-r.height/2,len=Math.hypot(x,z),scale=len>42?42/len:1;stick={x:x*scale/42,z:z*scale/42};$('stick').style.transform='translate(calc(-50% + '+x*scale+'px),calc(-50% + '+z*scale+'px))'}
$('joystick').addEventListener('pointerdown',e=>{if(state.phase!=='playing')return;e.preventDefault();pointer=e.pointerId;$('joystick').setPointerCapture(pointer);steer(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===pointer)steer(e)});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(event,()=>{pointer=null;clearMovement()});
document.querySelectorAll('[data-emblem]').forEach(b=>b.onclick=()=>chooseEmblem(b.dataset.emblem));document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.symbol)));$('puzzle-replay').onclick=showSequence;$('start').onclick=()=>begin();$('restart').onclick=reset;$('play-again').onclick=reset;$('interact').onclick=interact;$('difficulty').onchange=()=>{$('mode-explanation').textContent='Find '+modes[$('difficulty').value].target+' coins. No timer. No coins lost.'};$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',String(sound));$('sound').style.opacity=sound?'1':'.55';tone()};for(const id of ['start-dialog','puzzle-dialog','reward-dialog'])$(id).addEventListener('cancel',e=>e.preventDefault());
if(document.modelContext?.registerTool){for(const tool of [{name:'read_adventure',description:'Read current adventure progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:snapshot},{name:'start_adventure',description:'Start a new adventure, replacing current progress.',inputSchema:{type:'object',properties:{emblem:{type:'string',enum:['sun','moon','mountain']},difficulty:{type:'string',enum:['demo','explorer','adventurer']}},required:['emblem','difficulty'],additionalProperties:false},execute:input=>{if(!input||!emblems[input.emblem]||!modes[input.difficulty])throw Error('Choose a valid emblem and difficulty.');chooseEmblem(input.emblem);$('difficulty').value=input.difficulty;return begin(input.difficulty)}}])try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}
function interact(){if(ready()&&nearShrine())awaken();else if(Math.hypot(player.position.x-3,player.position.z-5)<2)openLoom()}
function continueJourney(){if(state.tier>=milestones.length-1)return;state.tier++;state.target=milestones[state.tier].coins;state.earned=false;state.phase='playing';$('reward-dialog').close();state.coins.forEach(c=>c.locked=c.id>=state.target);update();notify('New coins appeared. Next keepsake: '+milestones[state.tier].title);$('game').focus()}
initKeepsakes({info:snapshot,pause:()=>{if(state.phase!=='paused')pausedFrom=state.phase;state.phase='paused';clearMovement()},resume:()=>{state.phase=pausedFrom;if(state.phase==='reward'&&!$('reward-dialog').open)$('reward-dialog').showModal();else $('game').focus()},woven:()=>notify('Your weaving has become a rug design.')});
$('continue').onclick=continueJourney;$('reward-products').onclick=()=>{$('reward-dialog').close();openStudio('scarf')};
update();$('loading').hidden=true;$('start-dialog').showModal();requestAnimationFrame(frame);
